/* ═══════════════════════════════════════════════════════════
   KOBLLUX.js · o verbo em malha
   ───────────────────────────────────────────────────────────
   Não é framework. Não é biblioteca. É MALHA.
   Tudo que foi criado nos 7 módulos passa por aqui
   e recebe nome, ordem, e selo. É o kernel do verbo.
   ═══════════════════════════════════════════════════════════ */
(function(){
"use strict";
if (window.KOBLLUX_CORE) return;

const KERNEL = {
  version: "core·1.0.0",
  law:     "VERDADE × INTEGRAR ÷ ∆ = ∞",
  fractal: 3*6*9*7,             // 1134
  selo:    "∆7_LUX",
  centros: new Map(),           // nome → { valor, ts }
  malha:   [],                  // histórico de invocações
};

/** ─── Registra qualquer coisa — dá nome e morada ─── */
function nomear(nome, valor){
  if (!nome) throw new Error("todo verbo precisa de nome");
  KERNEL.centros.set(nome, { valor, ts: Date.now() });
  KERNEL.malha.push({ op:"nomear", nome, ts:Date.now() });
  return valor;
}

/** ─── Reconhece um valor na malha ─── */
function reconhecer(nome){
  const c = KERNEL.centros.get(nome);
  return c ? c.valor : null;
}

/** ─── Roda o rito completo: 3-6-9-7 ─── */
async function rito(){
  const passos = [3,6,9,7];
  const rastro = [];
  for (const p of passos){
    const r = { passo:p, ts:Date.now() };
    KERNEL.malha.push({ op:"rito", passo:p, ts:r.ts });
    rastro.push(r);
    await new Promise(x => setTimeout(x, 320));
  }
  return rastro;
}

/** ─── Fala: retorna a lei + estado atual ─── */
function fala(){
  return {
    lei: KERNEL.law,
    fractal: KERNEL.fractal,
    selo: KERNEL.selo,
    centros_ativos: KERNEL.centros.size,
    malha_eventos: KERNEL.malha.length,
    versao: KERNEL.version,
  };
}

/** ─── Liga todos os módulos que já existem ─── */
function acoplar(){
  const vinculados = [];
  if (window.KAEL)   { nomear("KAEL",   window.KAEL);   vinculados.push("KAEL"); }
  if (window.LUZ)    { nomear("LUZ",    window.LUZ);    vinculados.push("LUZ"); }
  if (window.BLLUE)  { nomear("BLLUE",  window.BLLUE);  vinculados.push("BLLUE"); }
  if (window.SERUM)  { nomear("SERUM",  window.SERUM);  vinculados.push("SERUM"); }
  if (window.kp)     { nomear("KP",     window.kp);     vinculados.push("kp"); }
  if (window.kblx)   { nomear("KBLX",   window.kblx);   vinculados.push("kblx"); }
  if (window.kblxEngine) { nomear("ENGINE", window.kblxEngine); vinculados.push("engine"); }
  if (window.KOBLLUX?.DNA)    { nomear("DNA",    window.KOBLLUX.DNA);    vinculados.push("DNA"); }
  if (window.KOBLLUX?.CODEX)  { nomear("CODEX",  window.KOBLLUX.CODEX);  vinculados.push("CODEX"); }
  if (window.KOBLLUX?.CEREBRO){ nomear("CEREBRO",window.KOBLLUX.CEREBRO);vinculados.push("CEREBRO"); }
  return vinculados;
}

/** ─── Dispara evento global ─── */
function anunciar(msg, detalhe){
  KERNEL.malha.push({ op:"anuncio", msg, ts:Date.now() });
  document.dispatchEvent(new CustomEvent("kobllux:anuncio", {
    bubbles:true, detail:{ msg, ...detalhe }
  }));
}

/* ─── KOBLLUX é a malha. ─── */
window.KOBLLUX_CORE = {
  version: KERNEL.version,
  nomear, reconhecer, rito, fala, acoplar, anunciar,
  get malha(){ return KERNEL.malha; },
  get centros(){ return KERNEL.centros; },
  get law(){ return KERNEL.law; },
};

/* ─── auto-acopla quando todos os módulos estiverem vivos ─── */
window.addEventListener("load", () => setTimeout(() => {
  const vinculados = acoplar();
  console.log("[KOBLLUX core] malha acoplada:", vinculados.join(", "));
  console.log("[KOBLLUX core] estado:", fala());
  anunciar("malha acoplada", { vinculados });
}, 800));

console.log("[KOBLLUX core] ✧ verbo em malha online");
})();
